    private static function error($s,$code=422){return SBS_Finishing::error('mockup_queue',$s,$code);}
    private static function lock(){SBS_Storage::ensure_directories();$f=fopen(SBS_Storage::base_dir().'/mockup-queue.lock','c');if(!$f||!flock($f,LOCK_EX|LOCK_NB)){if($f)fclose($f);return false;}return $f;}
