    public static function state(){return array('templates'=>array_values((array)get_option('sbs_mockup_templates',array())),'artwork'=>self::artwork(),'queue'=>get_option('sbs_mockup_queue',null),'defaults'=>get_option('sbs_mockup_defaults',array()),'sync'=>get_option('sbs_mockup_sync',array()));}
    public static function artwork(){ $out=array();$links=(array)get_option('sbs_mockup_links',array());foreach(glob(SBS_Storage::base_dir().'/finishing/*.json')?:array() as $p){$r=json_decode(@file_get_contents($p),true);if(!is_array($r))continue;$asset=SBS_Mockups::artwork($r);if(!$asset)continue;$uuid=$r['uuid'];$id=$links[$uuid]['code']??($r['links']['sb_id']??'');$out[]=array('id'=>$uuid,'title'=>$r['title'],'series'=>$r['series']??'','code'=>preg_match('/^[A-Z]{2}[0-9]{4}$/D',(string)$id)?$id:'','asset'=>$asset,'reference'=>$links[$uuid]['reference']??null,'reference_status'=>!empty($links[$uuid]['reference'])?'Linked':($links[$uuid]['status']??'Missing'),'folder_id'=>!empty($r['drive']['verified'])?($r['drive']['folder_id']??null):null); }return $out;}
    private static function category($s){return array_key_exists((string)$s,self::FOLDERS);}
    public static function templates($q){$lock=self::lock();if(!$lock)return self::error('Template library is busy. Retry.',409);try{
        $items=(array)get_option('sbs_mockup_templates',array());$op=$q->get_param('operation');$id=(string)$q->get_param('id');$item=$items[$id]??null;
        if($op==='import'){$category=(string)$q->get_param('category');if(!self::category($category))return self::error('Choose Men/Women and Model/Flat Lay.');$file=$q->get_file_params()['file']??null;if(!$file||!empty($file['error'])||($file['size']??0)>67108864)return self::error('Choose a photo up to 64 MB.');$size=@getimagesize($file['tmp_name']);if(!$size||!in_array($size['mime'],array('image/png','image/jpeg','image/webp'),true)||$size[0]*$size[1]>40000000)return self::error('Use PNG/JPEG/WebP up to 40 million pixels.');$hash=hash_file('sha256',$file['tmp_name']);foreach($items as $t){if(($t['asset']['sha256']??'')===$hash&&($t['category']??'')===$category)return array('template'=>$t,'reused'=>true);}$asset=SBS_Storage::store_upload($file,'mockups',0,'mockup_template',sanitize_text_field($file['name']));if(is_wp_error($asset))return $asset;$item=self::new_template($asset,$category,$items);$items[$item['id']]=$item;
        }elseif($op==='delete'){if(!$item)return self::error('Template is no longer in the library.',404);if($q->get_param('confirm')!==true)return self::error('Confirm this template deletion.');$queue=get_option('sbs_mockup_queue',null);if($queue&&in_array($id,$queue['templates'],true)&&empty($queue['finished']))return self::error('This template belongs to a saved queue. Finish or discard that queue first.',409);if(($item['asset']['role']??'')!=='mockup_template')return self::error('This older shared template cannot be permanently deleted here.');foreach($items as $other){if($other['id']!==$id&&$other['asset']['id']===$item['asset']['id'])return self::error('Another template uses this image.');}$ignored=(array)get_option('sbs_mockup_ignored',array());if(!empty($item['drive_id']))$ignored[$item['drive_id']]=true;self::save('sbs_mockup_ignored',$ignored);$removed=SBS_Storage::delete_asset($item['asset']['id']);if(is_wp_error($removed))return $removed;if(!empty($item['thumbnail'])&&($item['thumbnail']['role']??'')==='mockup_thumbnail')SBS_Storage::delete_asset($item['thumbnail']['id']);unset($items[$id]);$defaults=(array)get_option('sbs_mockup_defaults',array());foreach($defaults as $k=>$v){if($v===$id)unset($defaults[$k]);}self::save('sbs_mockup_defaults',$defaults);
