    private static function new_template($a,$category,$items,$drive=null){$thumbnail=null;if(class_exists('Imagick')){try{$im=new Imagick(SBS_Storage::absolute_path($a));$im->thumbnailImage(640,640,true);$im->setImageFormat('png');$thumb=SBS_Storage::store_bytes($im->getImageBlob(),'thumbnail.png','image/png','mockups',0,'mockup_thumbnail','Gallery preview');if(!is_wp_error($thumb))$thumbnail=$thumb;$im->clear();}catch(Throwable $e){}}$label=$a['filename'];$names=array_column($items,'label');$base=pathinfo($label,PATHINFO_FILENAME);$ext=pathinfo($label,PATHINFO_EXTENSION);for($n=2;in_array($label,$names,true);$n++)$label=$base.'-'.$n.'.'.$ext;return array('id'=>wp_generate_uuid4(),'label'=>$label,'category'=>$category,'asset'=>$a,'thumbnail'=>$thumbnail,'mask'=>null,'calibration'=>null,'revision'=>1,'drive_id'=>$drive,'created_at'=>gmdate('c'));}
    public static function sync($q=null){$lock=self::lock();if(!$lock)return self::error('An import is already running.',409);try{$items=(array)get_option('sbs_mockup_templates',array());$report=array('at'=>gmdate('c'),'imported'=>0,'errors'=>array());foreach(self::FOLDERS as $category=>$folder){$files=SBS_Google_Drive::mockup_source_files($folder);if(is_wp_error($files)){$report['errors'][]=$category.': '.$files->get_error_message();continue;}foreach($files as $file){if(!empty(get_option('sbs_mockup_ignored',array())[$file['id']]))continue;$known=false;foreach($items as $t){if(($t['drive_id']??null)===$file['id']){$known=true;break;}}if($known)continue;$a=SBS_Google_Drive::mockup_source_asset($file,$folder);if(is_wp_error($a)){$report['errors'][]=$file['name'].': '.$a->get_error_message();continue;}$duplicate=false;foreach($items as $t){if(($t['asset']['sha256']??'')===$a['sha256']&&($t['category']??'')===$category){$duplicate=true;break;}}if(!$duplicate){$t=self::new_template($a,$category,$items,$file['id']);$items[$t['id']]=$t;$report['imported']++;self::save('sbs_mockup_templates',$items);if($report['imported']>=5){$report['more']=true;self::save('sbs_mockup_sync',$report);return $report;}}}}$arts=self::artwork();$cursor=(int)get_option('sbs_mockup_ref_cursor',0);$links=(array)get_option('sbs_mockup_links',array());$end=min(count($arts),$cursor+10);for($n=$cursor;$n<$end;$n++){$art=$arts[$n];if($art['reference']||!$art['folder_id']||!$art['code'])continue;$ref=SBS_Google_Drive::mockup_reference($art);if(is_wp_error($ref)){$report['errors'][]=$art['code'].': '.$ref->get_error_message();continue;}$links[$art['id']]=array_merge($links[$art['id']]??array(),array('code'=>$art['code'],'status'=>$ref['status'],'reference'=>$ref['asset']??null));}self::save('sbs_mockup_links',$links);$report['more']=$end<count($arts);self::save('sbs_mockup_ref_cursor',$report['more']?$end:0);self::save('sbs_mockup_sync',$report);return $report;}finally{flock($lock,LOCK_UN);fclose($lock);}}
    public static function cron(){$r=self::sync();if(!is_wp_error($r)&&!empty($r['more']))wp_schedule_single_event(time()+60,'sbs_mockup_reconcile');}
    public static function queue($q){$lock=self::lock();if(!$lock)return self::error('Queue is busy. Retry.',409);try{
        $op=$q->get_param('operation');$queue=get_option('sbs_mockup_queue',null);$templates=(array)get_option('sbs_mockup_templates',array());
        if($op==='defaults'){$values=$q->get_param('templates');$defaults=(array)get_option('sbs_mockup_defaults',array());if(!is_array($values))return self::error('Choose template defaults.');foreach($values as $category=>$id){if(!self::category($category)||!isset($templates[$id])||($templates[$id]['category']??'')!==$category)return self::error('Invalid template default.');$defaults[$category]=$id;}$group=$q->get_param('group');if(in_array($group,array('men','women'),true))$defaults['group']=$group;self::save('sbs_mockup_defaults',$defaults);return array('defaults'=>$defaults);}
