        }else{if(!$queue)return self::error('Start a queue first.');if((int)$q->get_param('revision')!==$queue['revision'])return self::error('Queue changed in another tab. Refresh to continue.',409);$i=$queue['index'];$row=$queue['items'][$i];if($op==='pause')$queue['paused']=true;elseif($op==='resume')$queue['paused']=false;elseif($op==='discard'){$queue['finished']=true;$queue['paused']=true;}elseif($op==='previous'){$queue['index']=max(0,$i-1);$queue['finished']=false;}elseif($op==='retry'){if(!empty($row['outputs']))$row['versions'][]=$row['outputs'];$row['outputs']=array();$row['revision']++;$row['status']='pending';$queue['items'][$i]=$row;}elseif($op==='download'){ $kind=$q->get_param('kind');if(!in_array($kind,array('Model','FlatLay'),true)||empty($row['outputs'][$kind]))return self::error('Render that output first.');$queue['items'][$i]['outputs'][$kind]['download_requested_at']=gmdate('c');}elseif(in_array($op,array('approve','reject','skip'),true)){if($op==='approve'&&count($row['outputs'])!==2)return self::error('Render and review both images before approval.');$queue['items'][$i]['status']=array('approve'=>'approved','reject'=>'rejected','skip'=>'skipped')[$op];$queue['items'][$i]['reason']=sanitize_text_field((string)$q->get_param('reason'));$queue['items'][$i]['reviewed_at']=gmdate('c');if($op==='approve'){$result=SBS_Google_Drive::save_mockup_pair($queue,$queue['items'][$i]);$queue['items'][$i]['drive']=is_wp_error($result)?array('status'=>'failed','message'=>$result->get_error_message()):array('status'=>'saved','result'=>$result);}$queue['index']=min(count($queue['items'])-1,$i+1);$queue['finished']=$i+1>=count($queue['items']);}elseif($op==='drive'){if($row['status']!=='approved')return self::error('Approve this pair before filing to Drive.');$result=SBS_Google_Drive::save_mockup_pair($queue,$row);$queue['items'][$i]['drive']=is_wp_error($result)?array('status'=>'failed','message'=>$result->get_error_message()):array('status'=>'saved','result'=>$result);}else return self::error('Unknown queue action.');$queue['revision']++;}
        $queue['audit'][]=array('at'=>gmdate('c'),'action'=>$op,'index'=>$queue['index']);if(!self::save('sbs_mockup_queue',$queue))return self::error('Queue could not be saved.');return array('queue'=>$queue);
    }finally{flock($lock,LOCK_UN);fclose($lock);}}
    public static function output($q){$lock=self::lock();if(!$lock)return self::error('Queue is busy.',409);try{$queue=get_option('sbs_mockup_queue',null);if(!$queue||$queue['id']!==$q->get_param('queue')||(int)$q->get_param('revision')!==$queue['revision']||$queue['paused']||$queue['finished'])return self::error('Refresh or resume this queue before rendering.',409);$kind=$q->get_param('kind');if(!in_array($kind,array('Model','FlatLay'),true))return self::error('Choose Model or FlatLay.');$i=$queue['index'];$row=$queue['items'][$i];if(!in_array($row['status'],array('pending','ready'),true))return self::error('Retry this reviewed item before rendering.');if(isset($row['outputs'][$kind]))return array('queue'=>$queue);$file=$q->get_file_params()['file']??null;$size=$file?@getimagesize($file['tmp_name']):false;if(!$size||$size['mime']!=='image/png'||$size[0]*$size[1]>40000000||$file['size']>100663296)return self::error('Output must be a PNG up to 40 MP / 96 MB.');$suffix='-V'.substr(str_replace('-','',$queue['id']),0,8).'-R'.$row['revision'];$name=$row['artwork']['code'].'-'.$kind.'-'.$queue['preset'].$suffix.'.png';$asset=SBS_Storage::store_upload($file,'mockups',0,'mockup_output',$name);if(is_wp_error($asset))return $asset;$row['outputs'][$kind]=array('asset'=>$asset,'filename'=>$name,'width'=>$size[0],'height'=>$size[1],'ratio'=>$size[0]/$size[1],'platform'=>$queue['preset'],'template'=>$queue['templates'][$kind==='Model'?0:1],'qa'=>sanitize_text_field((string)$q->get_param('qa')),'created_at'=>gmdate('c'));$row['status']=count($row['outputs'])===2?'ready':'pending';$queue['items'][$i]=$row;$queue['revision']++;if(!self::save('sbs_mockup_queue',$queue))return self::error('Output stored but queue could not be saved. Refresh before retrying.');return array('queue'=>$queue);}finally{flock($lock,LOCK_UN);fclose($lock);}}
